  AND p.PRTF_USE_YN = 'Y'
ORDER BY p.PRTF_UPDT_DT DESC, p.PRTF_SN DESC, pf.PRTF_FL_SORT_NO ASC


WHERE p.PRTF_SN = #{portfolioSn}
  AND p.USR_SN = #{userSn}
  AND p.PRTF_USE_YN = 'Y'
