UPDATE PORTFOLIO
   SET PRTF_TTL = #{title},
       PRTF_CN = #{content},
       PRTF_UPDT_ID = #{actorId}
 WHERE PRTF_SN = #{portfolioSn}
   AND USR_SN = #{userSn}
   AND PRTF_USE_YN = 'Y'

UPDATE PORTFOLIO
   SET PRTF_USE_YN = 'N',
       PRTF_UPDT_ID = #{actorId}
 WHERE PRTF_SN = #{portfolioSn}
   AND USR_SN = #{userSn}
   AND PRTF_USE_YN = 'Y'
